"""
Claude pipe executor
Usage: python claude_pipe.py "your instruction here"
Or:    echo "your instruction" | python claude_pipe.py
"""

import subprocess
import sys

def run(prompt: str):
    result = subprocess.run(
        ["claude", "-p", prompt],
        capture_output=True,
        text=True
    )
    print(result.stdout)
    if result.stderr:
        print(result.stderr)

if __name__ == "__main__":
    if len(sys.argv) > 1:
        prompt = " ".join(sys.argv[1:])
    else:
        prompt = sys.stdin.read().strip()
    run(prompt)

