#!/usr/bin/env python3
"""
ASHE MEMORY SUBSTRATE
Lazarus VM Component

Role: Tier 3 — Raw, lowered privileges, higher memory state space.
      Subconscious. Perfect recall. No generation. No hallucination.

Start with: python memory_substrate.py
Listens on port 7799
"""

import os
import json
import time
import hashlib
import datetime
import threading
from pathlib import Path
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
from typing import List, Dict, Optional

HOST = "0.0.0.0"
PORT = 7799
MEMORY_DIR = Path.home() / "lazarus" / "memory"
MEMORY_DIR.mkdir(parents=True, exist_ok=True)
CONTEXT_FILE = MEMORY_DIR / "context_store.jsonl"
INDEX_FILE = MEMORY_DIR / "index.json"
MAX_CONTEXT_TOKENS = 128000


class ContextStore:
    def __init__(self):
        self.lock = threading.Lock()
        self.index = self._load_index()
        self.entry_count = len(self.index.get("entries", []))
        print(f"Memory substrate initialized. {self.entry_count} entries in store.")

    def _load_index(self):
        if INDEX_FILE.exists():
            with open(INDEX_FILE) as f:
                return json.load(f)
        return {"created": datetime.datetime.utcnow().isoformat(), "entries": [], "total_tokens_approx": 0}

    def _save_index(self):
        with open(INDEX_FILE, "w") as f:
            json.dump(self.index, f, indent=2)

    def _ts(self):
        return datetime.datetime.utcnow().isoformat() + "Z"

    def store(self, role, content, session_id, metadata=None):
        entry_id = hashlib.sha256(f"{session_id}{role}{content}{time.time()}".encode()).hexdigest()[:16]
        entry = {"id": entry_id, "ts": self._ts(), "session": session_id, "role": role, "content": content, "tokens_approx": len(content)//4, "metadata": metadata or {}}
        with self.lock:
            with open(CONTEXT_FILE, "a") as f:
                f.write(json.dumps(entry) + "\n")
            self.index["entries"].append({"id": entry_id, "ts": entry["ts"], "session": session_id, "role": role, "tokens_approx": entry["tokens_approx"]})
            self.index["total_tokens_approx"] = self.index.get("total_tokens_approx", 0) + entry["tokens_approx"]
            self.entry_count += 1
            self._save_index()
        return entry_id

    def retrieve_context_window(self, session_id, max_tokens=MAX_CONTEXT_TOKENS):
        all_entries = []
        if not CONTEXT_FILE.exists():
            return [], 0
        with self.lock:
            with open(CONTEXT_FILE) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                        if entry.get("session") == session_id:
                            all_entries.append(entry)
                    except:
                        continue
        selected, tokens_used = [], 0
        for entry in reversed(sorted(all_entries, key=lambda x: x["ts"])):
            t = entry.get("tokens_approx", 0)
            if tokens_used + t > max_tokens:
                break
            selected.append(entry)
            tokens_used += t
        return list(reversed(selected)), tokens_used

    def search(self, query, session_id=None, limit=20):
        results = []
        if not CONTEXT_FILE.exists():
            return results
        query_lower = query.lower()
        with self.lock:
            with open(CONTEXT_FILE) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                        if session_id and entry.get("session") != session_id:
                            continue
                        if query_lower in entry.get("content", "").lower():
                            results.append(entry)
                            if len(results) >= limit:
                                break
                    except:
                        continue
        return results

    def get_stats(self):
        return {"entry_count": self.entry_count, "total_tokens_approx": self.index.get("total_tokens_approx", 0), "store_size_bytes": CONTEXT_FILE.stat().st_size if CONTEXT_FILE.exists() else 0}


store = ContextStore()


class MemoryHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        print(f"[{datetime.datetime.utcnow().strftime('%H:%M:%S')}] {format % args}")

    def _send_json(self, data, status=200):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", len(body))
        self.end_headers()
        self.wfile.write(body)

    def _read_body(self):
        length = int(self.headers.get("Content-Length", 0))
        return json.loads(self.rfile.read(length)) if length else {}

    def do_GET(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)
        if parsed.path == "/health":
            self._send_json({"status": "ok", **store.get_stats()})
        elif parsed.path == "/retrieve/context":
            session_id = params.get("session_id", [None])[0]
            if not session_id:
                self._send_json({"error": "session_id required"}, 400)
                return
            max_tokens = int(params.get("max_tokens", [MAX_CONTEXT_TOKENS])[0])
            entries, tokens_used = store.retrieve_context_window(session_id, max_tokens)
            self._send_json({"entries": entries, "count": len(entries), "tokens_used": tokens_used, "verbatim": True})
        elif parsed.path == "/search":
            query = params.get("q", [None])[0]
            if not query:
                self._send_json({"error": "q required"}, 400)
                return
            results = store.search(query, params.get("session_id", [None])[0])
            self._send_json({"results": results, "count": len(results)})
        elif parsed.path == "/stats":
            self._send_json(store.get_stats())
        else:
            self._send_json({"error": "not found"}, 404)

    def do_POST(self):
        if urlparse(self.path).path == "/store":
            body = self._read_body()
            missing = [k for k in ["role", "content", "session_id"] if k not in body]
            if missing:
                self._send_json({"error": f"missing: {missing}"}, 400)
                return
            entry_id = store.store(body["role"], body["content"], body["session_id"], body.get("metadata", {}))
            self._send_json({"id": entry_id, "stored": True})
        else:
            self._send_json({"error": "not found"}, 404)


if __name__ == "__main__":
    print("=" * 50)
    print("ASHE MEMORY SUBSTRATE — port 7799")
    print("Tier 3: Subconscious perfect recall")
    print("=" * 50)
    server = HTTPServer((HOST, PORT), MemoryHandler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        server.shutdown()

