function p(text, opts = {}) {
  return new Paragraph({
    alignment: opts.center ? AlignmentType.CENTER : opts.right ? AlignmentType.RIGHT : AlignmentType.JUSTIFIED,
    spacing: { before: opts.before ?? 160, after: opts.after ?? 160, line: opts.line ?? 276 },
    indent: opts.indent ? { firstLine: 720 } : {},
    children: [new TextRun({
      text,
      bold: opts.bold ?? false,
      italics: opts.italic ?? false,
      size: opts.size ?? 24,
      font: "Garamond",
      color: opts.color ?? "000000"
    })]
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 480, after: 240 },
    children: [new TextRun({ text, bold: true, size: 32, font: "Garamond", color: "1a1a2e" })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 360, after: 160 },
    children: [new TextRun({ text, bold: true, italics: true, size: 26, font: "Garamond", color: "16213e" })]
  });
}

function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    spacing: { before: 280, after: 120 },
    children: [new TextRun({ text, bold: true, size: 24, font: "Garamond", color: "0f3460" })]
  });
}

function rule() {
  return new Paragraph({
    spacing: { before: 240, after: 240 },
    border: { bottom: { style: "single", size: 4, color: "999999", space: 1 } },
